using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the response body.")]
    public static async Task<string> FetchApi(
        IHttpClientFactory httpClientFactory,
        [Description("The absolute URL to fetch")] string url,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("api");
        var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize the given text.")]
    public static ChatMessage Summarize(
        [Description("The text to summarize")] string text)
    {
        return new ChatMessage(
            ChatRole.User,
            $"Please provide a concise summary of the following text:\n\n{text}");
    }
}

